import{_ as o,l as i,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"长度扩展与 HMAC","description":"","frontmatter":{"title":"长度扩展与 HMAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/length-extension-hmac.md","filePath":"cs/length-extension-hmac.md","lastUpdated":1789023840000}'),m={name:"cs/length-extension-hmac.md"};function c(A,a,C,_,M,u){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="长度扩展与-hmac" tabindex="-1">长度扩展与 HMAC <a class="header-anchor" href="#长度扩展与-hmac" aria-label="Permalink to &quot;长度扩展与 HMAC&quot;">​</a></h1><div class="epigraph"><p>知道 Merkle–Damgård 的 $H(m)$ 往往等于知道链状态，于是可伪造 $H(m\\|\\mathrm{pad}\\|s)$ 而不知 $m$。HMAC 把密钥以嵌套哈希拌进去，关掉这条，并成为标准 MAC。</p><footer>—— Krawczyk, Bellare and Canetti, HMAC, RFC 2104；Bellare, Canetti and Krawczyk 的分析</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/sha3-sponge">海绵</a>从结构上弱化了长度扩展。缺口是：SHA-2 仍是 MD，<strong>裸哈希不能当 MAC</strong>。主干<a href="/cs/mac-signature">MAC 与签名</a>已点名 HMAC；本课把长度扩展收成机制。不给伪造操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若认证做成 \\(H(k\\|m)\\)，MD 下敌手可在未知 \\(m\\) 时扩展。\\(H(m\\|k)\\) 另有填充与碰撞问题。HMAC：\\(H(k\\oplus\\mathrm{opad}\\|H(k\\oplus\\mathrm{ipad}\\|m))\\)。缺口是理解「为何嵌套」，不是再定义 MAC 游戏。</p><h3 id="海绵也不要用裸-凑合" tabindex="-1">海绵也不要用裸 \\(H(k\\|m)\\) 凑合 <a class="header-anchor" href="#海绵也不要用裸-凑合" aria-label="Permalink to &quot;海绵也不要用裸 $H(k\\|m)$ 凑合&quot;">​</a></h3><p>KMAC 按海绵合同拌密钥。算法换了，域分离不能省。</p><p><span class="marginnote">RFC 2104。安全归约依赖压缩函数的 PRF 性质（Bellare 后来的证明）。本课不提供长度扩展的字节级配方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述 MD 状态与摘要的关系。给出 HMAC 嵌套。对照 AEAD 内建标签：HMAC 仍用于旧协议、HKDF、许多 API 签名。指出时序上 HMAC 比较应常数时间。</p>',12)),(e(),s(p,null,{default:r(()=>[h(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%AF%86%E9%92%A5%22%5D%20--%3E%20IN%5B%22%E5%86%85%E5%B1%82%E5%93%88%E5%B8%8C%20ipad%22%5D%0A%20%20M%5B%22%E6%B6%88%E6%81%AF%22%5D%20--%3E%20IN%0A%20%20IN%20--%3E%20OUTH%5B%22%E5%A4%96%E5%B1%82%E5%93%88%E5%B8%8C%20opad%22%5D%0A%20%20OUTH%20--%3E%20TAG%5B%22MAC%20%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MAC 证明持有 \\(k\\) 的人认过消息。长度扩展说明「抗碰撞哈希」≠「带密钥认证」。HMAC 把 PRF 需求放到哈希上，工程上可换 SHA-256/SHA-3。签名仍是非对称，下一课生日界先回来管碰撞。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Poly1305、CMAC 写全。生日攻击下一课：碰撞的平方根界，既管哈希也管 CTR 分组。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MD 摘要可当链状态，裸 \\(H(k\\|m)\\) 不够。</li><li>HMAC 嵌套关长度扩展，是标准 MAC。</li><li>常数时间比较标签，避免再开预言。</li><li>下一课生日界：碰撞的定量。</li><li>出处：RFC 2104；Bellare, Canetti and Krawczyk；对照 FIPS 198-1。</li></ul>',8))])}const E=o(m,[["render",c]]);export{k as __pageData,E as default};
